insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('Microsoft Dynamics 365 Sales', 'dynamics-365-sales', 'CRM im Microsoft-Ökosystem', 'Vertriebs-CRM, das tief in Microsoft 365, Teams und Power Platform integriert ist.', '<p>Dynamics 365 Sales ist das CRM von Microsoft und entfaltet seine Stärken in Unternehmen, die bereits auf Microsoft 365 setzen. Outlook, Teams und Excel sind nahtlos integriert; über die Power Platform lassen sich Prozesse individuell erweitern.</p><p>Microsoft betreibt Rechenzentren in Deutschland und der EU.</p>', null, (select id from public.categories where slug = 'crm-software'), 56.3, 'EUR', 'month', true, 'user', true, null, false, true, '[{"name":"Sales Professional","price":56.3,"period":"month","unit":"user","features":["Kernfunktionen des Vertriebs"]},{"name":"Sales Enterprise","price":91,"period":"month","unit":"user","features":["Erweiterte Prognosen und Anpassung"],"highlighted":true},{"name":"Sales Premium","price":130,"period":"month","unit":"user","features":["KI-gestützter Vertrieb"]}]'::jsonb, 'bei jährlicher Zahlung', '["Kontakt- & Firmenverwaltung","Vertriebspipeline","Angebotserstellung","E-Mail-Integration","Marketing-Automation","Aufgaben & Wiedervorlagen","Berichte & Dashboards","Mobile App","Telefonie-Integration"]'::jsonb, '["Tiefe Microsoft-365-Integration","Power Platform","Copilot-Funktionen"]'::jsonb, '["Outlook","Microsoft Teams","Excel","Power BI","LinkedIn Sales Navigator"]'::jsonb, '["Nahtlos mit Microsoft 365","Sehr erweiterbar"]'::jsonb, '["Lizenzmodell komplex","Einführung meist über Partner"]'::jsonb, 'Unternehmen mit Microsoft-Ökosystem.', null, null, null, '[]'::jsonb, null, 'EU', true, true, null, '[]'::jsonb, true, 'USA', '2026-09-22', null, 'https://www.microsoft.com/de-de/dynamics-365/products/sales', 'keins', 'Microsoft Deutschland GmbH', 1975, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.1, 3.7, 3.7, 4, 4.7, 'Dynamics 365 Sales ist für Unternehmen interessant, die tief in der Microsoft-Welt arbeiten. Die Verzahnung mit Outlook, Teams und Business Central ist das stärkste Argument.', '<h3>Was das System leistet</h3><p>Microsofts Vertriebs-CRM deckt Leads, Verkaufschancen, Angebote, Prognosen und Berichte ab. Wer ohnehin Microsoft 365 nutzt, arbeitet mit vertrauten Oberflächen und hat Kontakte, E-Mails und Termine ohne Umwege im CRM.</p><h3>Preise</h3><p>Sales Professional kostet 56,30 € je Nutzer im Monat, Sales Enterprise 91 € und Sales Premium 130 €, jeweils bei jährlicher Zahlung. Eine kostenlose Testversion ist verfügbar.</p><h3>Fazit</h3><p>Für Microsoft-Häuser mit Business Central als ERP ist Dynamics 365 Sales der natürliche Partner. Für kleine Teams ohne Microsoft-Schwerpunkt sind Pipedrive oder HubSpot schneller eingeführt.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('SAP Business One', 'sap-business-one', 'ERP von SAP für kleine und mittlere Unternehmen', 'ERP-System für KMU mit Finanzen, Einkauf, Vertrieb, Lager und Produktion, on-premise oder gehostet.', '<p>SAP Business One ist die ERP-Lösung von SAP für kleine und mittlere Unternehmen. Finanzbuchhaltung, Einkauf, Vertrieb, Lager und Produktion laufen in einem integrierten System, das von zertifizierten Partnern eingeführt und angepasst wird.</p><p>Betrieben wird SAP Business One im eigenen Haus oder beim Partner gehostet.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), null, 'EUR', 'month', true, 'user', false, null, false, true, '[]'::jsonb, null, '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Produktion & Stücklisten","Finanzbuchhaltung","E-Rechnung (XRechnung/ZUGFeRD)","Mehrlager & Versand","CRM-Funktionen","Controlling & Berichte"]'::jsonb, '["SAP-Qualität für KMU","Großes Partnernetz","Branchenlösungen"]'::jsonb, '["DATEV","Shopware","Microsoft 365","SAP Analytics Cloud"]'::jsonb, '["Sehr leistungsfähig","Branchenlösungen verfügbar"]'::jsonb, '["Hohe Einführungskosten","Abhängigkeit vom Partner"]'::jsonb, 'Produzierende Mittelständler mit 20 bis 250 Mitarbeitenden.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'on-premise', null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sap.com/germany/products/erp/business-one.html', 'keins', 'SAP SE', 1972, 'Walldorf', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.1, 3.5, 3.6, 4, 4.8, 'SAP Business One ist die Mittelstandsvariante des Weltmarktführers. Funktional sehr stark, aber nur mit Partner einzuführen und entsprechend teuer.', '<h3>Einordnung</h3><p>Business One deckt Finanzen, Einkauf, Vertrieb, Lager, Produktion und Service ab und richtet sich an Unternehmen mit etwa 10 bis 250 Beschäftigten. Viele Betriebe entscheiden sich dafür, weil Kunden oder Konzernmütter bereits mit SAP arbeiten.</p><h3>Einführung und Kosten</h3><p>Das System wird immer über zertifizierte Partner verkauft und eingeführt. Preise gibt es nur auf Anfrage und hängen von Lizenzmodell, Nutzerzahl und Anpassungen ab. Rechnen Sie neben der Lizenz mit einem Einführungsprojekt.</p><h3>Fazit</h3><p>Für produzierende und handelnde Mittelständler mit internationaler Ausrichtung ist Business One eine sichere Wahl. Kleine Betriebe finden bei weclapp oder Odoo schnellere und günstigere Lösungen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Microsoft Dynamics 365 Business Central', 'dynamics-365-business-central', 'Cloud-ERP für den Mittelstand', 'Cloud-ERP mit Finanzen, Lager, Einkauf, Vertrieb und Projekten, eng verzahnt mit Microsoft 365.', '<p>Business Central ist das Cloud-ERP von Microsoft für kleine und mittlere Unternehmen und Nachfolger von Navision. Die deutsche Lokalisierung umfasst UStVA, DATEV-Export und E-Rechnung.</p><p>Die Einführung erfolgt meist über Microsoft-Partner, die Branchenerweiterungen mitbringen.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 69.3, 'EUR', 'month', true, 'user', true, 30, false, true, '[{"name":"Essentials","price":69.3,"period":"month","unit":"user","features":["Finanzen, Vertrieb, Einkauf, Lager"],"highlighted":true},{"name":"Premium","price":95.3,"period":"month","unit":"user","features":["Zusätzlich Service und Fertigung"]},{"name":"Team Members","price":6.9,"period":"month","unit":"user","features":["Lesen, Freigaben, einfache Bearbeitung"]}]'::jsonb, 'bei jährlicher Zahlung', '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Produktion & Stücklisten","Finanzbuchhaltung","E-Rechnung (XRechnung/ZUGFeRD)","Mehrlager & Versand","Controlling & Berichte"]'::jsonb, '["Deutsche Lokalisierung","Microsoft-365-Integration","Großes Partner-Ökosystem"]'::jsonb, '["Outlook","Excel","Power BI","DATEV","Shopify"]'::jsonb, '["Moderne Cloud-Plattform","Gut erweiterbar"]'::jsonb, '["Partnerabhängig","Lizenzkosten pro Nutzer"]'::jsonb, 'Mittelständler, die von Navision oder Einzellösungen umsteigen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'EU', true, true, null, '[]'::jsonb, true, 'USA', '2026-09-22', null, 'https://www.microsoft.com/de-de/dynamics-365/products/business-central', 'keins', 'Microsoft Deutschland GmbH', 1975, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.3, 3.9, 4, 4.1, 4.7, 'Business Central ist das Cloud-ERP von Microsoft für kleine und mittlere Unternehmen. Es verbindet eine sehr gute Finanzbuchhaltung mit Lager, Einkauf, Vertrieb und optionaler Fertigung.', '<h3>Was das System leistet</h3><p>Business Central ist der Nachfolger von Navision, einem der verbreitetsten ERP-Systeme im deutschen Mittelstand. Die deutsche Lokalisierung umfasst Umsatzsteuer-Voranmeldung, DATEV-Export und E-Rechnung, und die Integration in Outlook, Excel und Teams ist tief.</p><h3>Preise</h3><p>Essentials kostet 69,30 € je Nutzer im Monat, Premium mit Service und Fertigung 95,30 €, Team Members mit eingeschränkten Rechten 6,90 €, jeweils bei jährlicher Zahlung. Eine Testphase von 30 Tagen ist kostenlos. Für die Einführung arbeitet Microsoft mit Partnern, deren Kosten hinzukommen.</p><h3>Fazit</h3><p>Für Unternehmen mit 10 bis 250 Beschäftigten, die in der Microsoft-Welt arbeiten, ist Business Central eine der überzeugendsten ERP-Lösungen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('weclapp', 'weclapp', 'Cloud-ERP aus Deutschland', 'Cloud-ERP mit CRM, Warenwirtschaft, Projekten und Buchhaltung, ISO 27001, redundant in Deutschland gehostet.', '<p>weclapp ist ein Cloud-ERP aus Deutschland, das CRM, Warenwirtschaft, Projektmanagement, Helpdesk und Finanzbuchhaltung in einer Plattform zusammenführt. Die Lösung richtet sich an Handel, Dienstleister und leichte Fertigung.</p><p>Die Daten werden redundant in deutschen Rechenzentren gehostet; das Unternehmen ist nach ISO 27001 zertifiziert.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 39, 'EUR', 'month', true, 'user', true, 30, false, false, '[{"name":"ERP Starter","price":39,"period":"month","unit":"user","features":[]},{"name":"ERP Dienstleistung","price":95,"period":"month","unit":"user","features":["jährlich 86 €"],"highlighted":true},{"name":"ERP Handel","price":179,"period":"month","unit":"user","features":["jährlich 163 €"]}]'::jsonb, null, '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Produktion & Stücklisten","Finanzbuchhaltung","E-Commerce-Anbindung","E-Rechnung (XRechnung/ZUGFeRD)","Mehrlager & Versand","CRM-Funktionen","Controlling & Berichte"]'::jsonb, '["ISO 27001, Hosting in Deutschland","CRM bis FiBu in einer Cloud","Schnelle Einführung"]'::jsonb, '["DATEV","Shopify","Shopware","Amazon","WooCommerce","DHL"]'::jsonb, '["Deutsches Hosting und ISO 27001","Breiter Funktionsumfang"]'::jsonb, '["Produktion eher einfach","Einarbeitung nötig"]'::jsonb, 'Händler und Dienstleister mit 5 bis 200 Mitarbeitenden.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'Deutschland', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.weclapp.com/de/', 'keins', 'weclapp SE', 2008, 'Frankfurt am Main', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 4.1, 4.1, 4.1, 4.4, 'weclapp aus Marburg ist ein Cloud-ERP, das sich ohne großes Einführungsprojekt starten lässt. Für Dienstleister und Händler mit bis zu 50 Beschäftigten ist es eine sehr gute Wahl.', '<h3>Das Konzept</h3><p>weclapp verbindet CRM, Warenwirtschaft, Projekte, Buchhaltung und Fulfillment in einer Cloud-Anwendung. Die Tarife sind nach Branchen geschnitten, was die Auswahl einfacher macht als bei klassischen ERP-Systemen.</p><h3>Preise</h3><p>ERP Starter kostet 39 € je Nutzer im Monat. ERP Dienstleistung liegt bei 95 €, bei jährlicher Zahlung bei 86 €. ERP Handel kostet 179 €, jährlich 163 €. Ab zehn Nutzern gibt es individuelle Konditionen. Alle Tarife lassen sich 30 Tage kostenlos testen, der Test endet automatisch.</p><h3>Fazit</h3><p>Wer sein Unternehmen aus mehreren Einzeltools in ein System überführen will, findet in weclapp eine moderne, deutsche Lösung mit Rechenzentrum in Deutschland.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('Xentral', 'xentral', 'ERP für E-Commerce und Handel', 'ERP aus Augsburg für wachsende E-Commerce- und Handelsunternehmen mit Marktplatz- und Shop-Anbindungen.', '<p>Xentral richtet sich an wachsende Handelsunternehmen, insbesondere im E-Commerce. Aufträge aus Shops und Marktplätzen, Lager, Versand und Einkauf laufen in einem System zusammen.</p><p>Die Finanzdaten werden per DATEV-Export an die Steuerkanzlei übergeben.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 99, 'EUR', 'month', true, 'account', true, 14, false, true, '[{"name":"Launch","price":99,"period":"month","unit":"account","features":["Bis 500.000 € Jahresumsatz","Bis 1.200 Aufträge im Monat"]},{"name":"Starter","price":349,"period":"month","unit":"account","features":["500 Aufträge im Monat inklusive"]},{"name":"Business","price":649,"period":"month","unit":"account","features":["Automatisierung und API"],"highlighted":true},{"name":"Pro","price":849,"period":"month","unit":"account","features":["Komplexe Workflows"]}]'::jsonb, 'unbegrenzte Nutzer; Launch bis 500.000 € Jahresumsatz', '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Produktion & Stücklisten","E-Commerce-Anbindung","E-Rechnung (XRechnung/ZUGFeRD)","Mehrlager & Versand","Controlling & Berichte"]'::jsonb, '["Starke E-Commerce-Anbindung","Versandprozesse automatisiert","DATEV-Export"]'::jsonb, '["Shopify","Shopware","Amazon","eBay","DHL","DPD","DATEV"]'::jsonb, '["Ideal für Online-Handel","Viele Marktplatz-Schnittstellen"]'::jsonb, '["Weniger geeignet für Produktion","Preise steigen mit Umsatz und Auftragsvolumen"]'::jsonb, 'E-Commerce-Händler im Wachstum.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://xentral.com/de', 'keins', 'Xentral ERP Software GmbH', null, 'Augsburg', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 4.2, 3.8, 4, 4.4, 'Xentral ist das ERP für wachsende Onlinehändler mit vielen Aufträgen. Unbegrenzte Nutzer in allen Tarifen sind ein starkes Argument, die Preise steigen aber mit Umsatz und Auftragsvolumen.', '<h3>Einordnung</h3><p>Das Augsburger Unternehmen hat sich auf den E-Commerce spezialisiert. Aufträge aus Shops und Marktplätzen, Lager, Versand und Buchhaltungsexport laufen in einem System zusammen.</p><h3>Preise</h3><p>Launch kostet 99 € im Monat für Unternehmen bis 500.000 € Jahresumsatz und 1.200 Aufträge im Monat. Starter liegt bei 349 € mit 500 inklusiven Aufträgen, Business bei 649 € mit Automatisierung und API, Pro bei 849 €. Alle Tarife enthalten unbegrenzt viele Nutzer. Eine Testphase von 14 Tagen ist kostenlos und endet automatisch.</p><h3>Fazit</h3><p>Für Händler, die aus JTL oder Einzeltools herauswachsen, ist Xentral eine naheliegende Wahl. Für Dienstleister ohne Warenfluss passt weclapp besser.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Odoo', 'odoo', 'Modulares Open-Source-ERP', 'Modulares ERP mit Apps für Buchhaltung, CRM, Lager, Fertigung, E-Commerce und mehr, mit kostenloser Einzel-App.', '<p>Odoo ist ein modulares ERP, bei dem Unternehmen einzelne Apps wie CRM, Lager, Fertigung, Buchhaltung oder Website nach Bedarf kombinieren. Eine App ist dauerhaft kostenlos nutzbar.</p><p>Für Deutschland stehen Lokalisierungen für SKR 03/04, UStVA und DATEV-Export bereit; die Cloud-Variante wird in der EU gehostet.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 0, 'EUR', 'month', true, 'user', true, null, true, false, '[{"name":"One App Free","price":0,"period":"month","unit":"user","features":["Eine App, unbegrenzte Nutzer"]},{"name":"Standard","price":8.95,"period":"month","unit":"user","features":["Alle Apps in Odoo Online","jährlich 7,25 €"],"highlighted":true},{"name":"Custom","price":13.6,"period":"month","unit":"user","features":["Odoo Studio, Multi-Company, API","jährlich 10,90 €"]}]'::jsonb, null, '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Produktion & Stücklisten","Finanzbuchhaltung","E-Commerce-Anbindung","E-Rechnung (XRechnung/ZUGFeRD)","Kassensystem (TSE)","Mehrlager & Versand","CRM-Funktionen","Controlling & Berichte"]'::jsonb, '["Modular erweiterbar","Open-Source-Kern","Eine App kostenlos"]'::jsonb, '["DATEV","Shopify","Amazon","PayPal","Stripe"]'::jsonb, '["Enorm flexibel","Faire Einstiegspreise"]'::jsonb, '["Deutsche Lokalisierung braucht Partner-Know-how","Viele Module = komplexe Einführung"]'::jsonb, 'Unternehmen, die schrittweise ein ERP aufbauen.', null, 'teilweise', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'EU', true, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Belgien', '2026-09-22', null, 'https://www.odoo.com/de_DE', 'keins', 'Odoo S.A.', 2005, 'Grand-Rosière (Belgien)', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.2, 3.9, 4.6, 3.7, 4.7, 'Odoo ist das flexibelste ERP-System in diesem Vergleich und dank Open-Source-Kern sehr günstig. Die deutsche Lokalisierung sollte vor dem Start mit einem erfahrenen Partner geprüft werden.', '<h3>Das Baukastenprinzip</h3><p>Odoo besteht aus Apps für CRM, Verkauf, Lager, Fertigung, Buchhaltung, Website, Onlineshop und vieles mehr. Man startet mit dem, was man braucht, und ergänzt später.</p><h3>Preise</h3><p>Eine einzelne App ist dauerhaft kostenlos, mit unbegrenzt vielen Nutzern. Standard mit allen Apps kostet 8,95 € je Nutzer im Monat, bei jährlicher Zahlung 7,25 €. Custom mit Odoo Studio, Multi-Company und API liegt bei 13,60 €, jährlich 10,90 €. Hosting, Wartung und Support sind enthalten.</p><h3>Worauf Sie achten sollten</h3><p>Für die deutsche Buchhaltung mit DATEV-Export, GoBD-Anforderungen und E-Rechnung braucht es eine sorgfältige Einrichtung. Viele Unternehmen arbeiten dafür mit einem deutschen Odoo-Partner zusammen, dessen Kosten in die Kalkulation gehören.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Sage 100', 'sage-100', 'ERP für den Mittelstand', 'ERP-System für mittelständische Unternehmen mit Rechnungswesen, Warenwirtschaft und Produktion.', '<p>Sage 100 ist eine ERP-Lösung für den deutschen Mittelstand mit starkem Rechnungswesen, Warenwirtschaft und optionaler Produktion. Sie wird lokal oder beim Partner betrieben.</p><p>Seit dem 01.01.2026 gelten für Bestandsverträge angepasste Preise; Konditionen werden individuell vereinbart.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 56, 'EUR', 'month', true, 'user', false, null, false, true, '[{"name":"Warenwirtschaft","price":56,"period":"month","unit":"user","features":["Kunden- und Lieferantenverwaltung","Bestellwesen und Kommissionierung","Lager und Inventur","Seriennummern und Chargen"]},{"name":"Rechnungswesen","price":58,"period":"month","unit":"user","features":["Finanz- und Anlagenbuchhaltung","Controlling und Dashboard","Mahnwesen, offene Posten","UStVA per ELSTER"],"highlighted":true},{"name":"Produktion","price":90,"period":"month","unit":"user","features":["Einzel-, Projekt- und Serienfertigung","Kalkulation und BDE","Grafische Ressourcenplanung"]}]'::jsonb, 'je Modul, bei jährlicher Zahlung, 12 Monate Laufzeit', '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Produktion & Stücklisten","Finanzbuchhaltung","E-Rechnung (XRechnung/ZUGFeRD)","Mehrlager & Versand","Controlling & Berichte"]'::jsonb, '["Starkes Rechnungswesen","Für den deutschen Mittelstand entwickelt"]'::jsonb, '["DATEV","Microsoft Office","Sage HR Suite"]'::jsonb, '["Solide FiBu","Lange Marktpräsenz"]'::jsonb, '["Einarbeitung braucht Zeit","Einführung meist mit Partner"]'::jsonb, 'Mittelständler mit Fokus auf Rechnungswesen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'on-premise', null, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-100/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.3, 3.9, 4.1, 4.3, 4.7, 'Sage 100 ist ein bewährtes ERP für den deutschen Mittelstand, das Warenwirtschaft, Rechnungswesen und Produktion modular verbindet. Transparente Modulpreise machen die Kalkulation einfacher als bei vielen Wettbewerbern.', '<h3>Einordnung</h3><p>Sage 100 richtet sich an Unternehmen, die über Sage 50 hinausgewachsen sind oder individuelle Prozesse abbilden müssen. Die Module Warenwirtschaft, Rechnungswesen und Produktion lassen sich einzeln oder kombiniert einsetzen, ergänzt durch Lösungen wie xRM, DMS oder einen Webshop.</p><h3>Stärken</h3><p>Das Rechnungswesen bietet Finanz- und Anlagenbuchhaltung, Controlling mit Dashboard, Mahnwesen und die Umsatzsteuer-Voranmeldung über ELSTER, bei unbegrenzter Mandantenzahl. Die Warenwirtschaft deckt Bestellwesen, Kommissionierung, Lager, Inventur sowie Seriennummern und Chargen ab. Das Produktionsmodul eignet sich für Einzel-, Projekt- und Serienfertiger mit Kalkulation und Betriebsdatenerfassung.</p><p>Über eine API lassen sich Partnerlösungen anbinden, und Sage verfügt über ein dichtes Partnernetz in Deutschland für Einführung und Betreuung.</p><h3>Preise</h3><p>Die Warenwirtschaft beginnt bei 56 € je Nutzer im Monat, das Rechnungswesen bei 58 € und die Produktion bei 90 €, bei jährlicher Zahlung und zwölf Monaten Mindestlaufzeit. Für ein konkretes Angebot und eine Produkttour bietet Sage eine kostenlose Beratung an.</p><h3>Für wen es passt</h3><p>Für mittelständische Händler und Fertiger mit 20 bis 250 Beschäftigten, die ein deutsches ERP mit klarer Preisstruktur suchen, gehört Sage 100 auf die Auswahlliste.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('myfactory', 'myfactory', 'Cloud-ERP für Handel, Dienstleistung und Produktion', 'Cloud-ERP mit Warenwirtschaft, Finanzbuchhaltung, CRM und Produktion für den Mittelstand.', '<p>myfactory ist ein Cloud-ERP für kleine und mittlere Unternehmen aus Handel, Dienstleistung und Fertigung. Warenwirtschaft, Finanzbuchhaltung, CRM und Produktion sind in einer browserbasierten Anwendung integriert.</p><p>Das Hosting erfolgt in Deutschland.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), null, 'EUR', 'month', true, 'user', true, null, false, true, '[]'::jsonb, null, '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Produktion & Stücklisten","Finanzbuchhaltung","E-Commerce-Anbindung","E-Rechnung (XRechnung/ZUGFeRD)","CRM-Funktionen","Controlling & Berichte"]'::jsonb, '["Vollständig browserbasiert","Integrierte FiBu","Hosting in Deutschland"]'::jsonb, '["DATEV","Shopware","Outlook"]'::jsonb, '["Echte Cloud-Lösung","Breiter Funktionsumfang"]'::jsonb, '["Weniger bekannt","Preis nur auf Anfrage"]'::jsonb, 'KMU, die ein komplettes ERP in der Cloud suchen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.myfactory.com', 'keins', 'myfactory International GmbH', null, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4, 3.8, 3.9, 4, 4.5, 'myfactory ist ein Cloud-ERP für den Mittelstand mit starker Warenwirtschaft und Finanzbuchhaltung. Es richtet sich an Unternehmen, die eine vollständige Branchenlösung ohne eigenen Server suchen.', '<h3>Einordnung</h3><p>myfactory war einer der frühen Anbieter eines vollständigen ERP-Systems im Browser. Warenwirtschaft, Finanzbuchhaltung, CRM und Produktion sind integriert, Branchenpakete gibt es unter anderem für Großhandel und Fertigung.</p><h3>Kosten</h3><p>Preise gibt es auf Anfrage, meist über Partner. Eine Demo ist kostenlos.</p><h3>Fazit</h3><p>Für mittelständische Händler und Fertiger, die auf die Cloud setzen, ist myfactory eine solide Alternative zu Business Central und weclapp.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false)
